// src/pages/Login/LoginPage.jsx
import { useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import { useAuth } from "../../context/AuthContext";
import { useToast } from "../../context/ToastContext";
import { login as apiLogin } from "../../services/authService";
import "../../styles/components.css";
import styles from "./LoginPage.module.css";

export default function LoginPage() {
  const [form, setForm]     = useState({ credential: "", password: "" });
  const [error, setError]   = useState("");
  const [loading, setLoading] = useState(false);
  const { login }           = useAuth();
  const showToast           = useToast();
  const navigate            = useNavigate();

  function handleChange(e) {
    setForm((p) => ({ ...p, [e.target.name]: e.target.value }));
    setError("");
  }

  async function handleSubmit(e) {
    e.preventDefault();
    if (!form.credential || !form.password) { setError("يرجى ملء جميع الحقول"); return; }
    setLoading(true);
    try {
      const res = await apiLogin(form.credential, form.password);
      login(res.data.user, res.data.token);
      showToast(`مرحباً ${res.data.user.name} 👋`);
      navigate("/library");
    } catch (err) {
      const msg = err.response?.data?.errors?.credential?.[0]
               || err.response?.data?.message
               || "حدث خطأ، حاول مرة أخرى";
      setError(msg);
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="auth-page">
      <div className="auth-card">
        <div className="auth-logo">
          <div className="auth-logo-icon">
            <svg width="20" height="20" fill="white" viewBox="0 0 24 24"><path d="M4 4h16v16H4V4zm2 2v12h12V6H6zm2 2h8v2H8V8zm0 4h5v2H8v-2z"/></svg>
          </div>
          <span className="auth-logo-text">BookShelf</span>
        </div>
        <h1 className="auth-title">مرحباً بعودتك 👋</h1>
        <p className="auth-subtitle">سجّل دخولك للوصول لمكتبتك الشخصية</p>
        {error && <div className="alert alert-error">{error}</div>}
        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label className="form-label">اسم المستخدم أو الإيميل</label>
            <input className="form-input" name="credential" placeholder="اسم المستخدم أو الإيميل" value={form.credential} onChange={handleChange} autoComplete="username" />
          </div>
          <div className="form-group">
            <label className="form-label">كلمة المرور</label>
            <input className="form-input" name="password" type="password" placeholder="كلمة المرور" value={form.password} onChange={handleChange} autoComplete="current-password" />
          </div>
          <div className="auth-forgot"><Link to="/forgot-password">نسيت كلمة المرور؟</Link></div>
          <button type="submit" className="btn btn-primary btn-full" disabled={loading}>
            {loading ? "جاري التحقق..." : "تسجيل الدخول"}
          </button>
        </form>
        <div className="auth-divider">
          <div className="auth-divider-line" /><span className="auth-divider-text">أو</span><div className="auth-divider-line" />
        </div>
        <button className="btn-google">
          <svg width="18" height="18" viewBox="0 0 48 48">
            <path fill="#EA4335" d="M24 9.5c3.54 0 6.71 1.22 9.21 3.6l6.85-6.85C35.9 2.38 30.47 0 24 0 14.62 0 6.51 5.38 2.56 13.22l7.98 6.19C12.43 13.72 17.74 9.5 24 9.5z"/>
            <path fill="#4285F4" d="M46.98 24.55c0-1.57-.15-3.09-.38-4.55H24v9.02h12.94c-.58 2.96-2.26 5.48-4.78 7.18l7.73 6c4.51-4.18 7.09-10.36 7.09-17.65z"/>
            <path fill="#FBBC05" d="M10.53 28.59c-.48-1.45-.76-2.99-.76-4.59s.27-3.14.76-4.59l-7.98-6.19C.92 16.46 0 20.12 0 24c0 3.88.92 7.54 2.56 10.78l7.97-6.19z"/>
            <path fill="#34A853" d="M24 48c6.48 0 11.93-2.13 15.89-5.81l-7.73-6c-2.18 1.48-4.97 2.29-8.16 2.29-6.26 0-11.57-4.22-13.47-9.91l-7.98 6.19C6.51 42.62 14.62 48 24 48z"/>
          </svg>
          تسجيل الدخول بـ Google
        </button>
        <div className="auth-footer">ما عندكش حساب؟ <Link to="/register">إنشاء حساب جديد</Link></div>
        <p className={styles.demoHint}>تجريبي: admin@bookshelf.com / admin123</p>
      </div>
    </div>
  );
}
